const status = $input.first().json;
const base = $('Kling MCP Image Submit').first().json;
const image_file = status.result_urls && status.result_urls[0];
if (!image_file) {
  throw new Error('Kling task marked done but no result_urls found for generation_id ' + status.generation_id);
}
const scenePadded = String(base.scene).padStart(2, '0');
const local_image_path = 'C:\\Users\\pc-11\\Desktop\\Kiko AI Studio\\Assets\\images\\' + base.episode_id + '_scene_' + scenePadded + '.png';
const original_prompt = base.original_prompt || base.base_image_prompt || '';
const optimized_image_prompt = base.optimized_image_prompt || base.prompt || base.image_prompt || '';
return [{
  json: {
    episode_id: base.episode_id,
    scene: base.scene,
    narration: base.narration,
    narration_en: base.narration_en,
    sfx_cue: base.sfx_cue,
    dialogue_lines: base.dialogue_lines || [],
    original_prompt,
    base_image_prompt: original_prompt,
    optimized_image_prompt,
    image_prompt: optimized_image_prompt,
    prompt: optimized_image_prompt,
    image_file,
    local_image_path,
  },
}];

const d = $input.first().json;
return [{
  json: {
    episode_id: d.episode_id,
    scene: d.scene,
    narration: d.narration,
    narration_en: d.narration_en,
    sfx_cue: d.sfx_cue,
    dialogue_lines: d.dialogue_lines || [],
    original_prompt: d.original_prompt || d.base_image_prompt || '',
    base_image_prompt: d.base_image_prompt || d.original_prompt || '',
    optimized_image_prompt: d.optimized_image_prompt || d.prompt || d.image_prompt || '',
    image_prompt: d.image_prompt || d.optimized_image_prompt || d.prompt || '',
    prompt: d.prompt || d.optimized_image_prompt || d.image_prompt || '',
    image_file: d.local_image_path,
  },
}];
